// ── Type-safe translator helper ──────────────────────────────
type TranslationDict = typeof translations;

export type Translator = {
  common:   (key: keyof TranslationDict["common"])   => string;
  nav:      (key: keyof TranslationDict["nav"])      => string;
  home:     (key: keyof TranslationDict["home"])     => string;
  shop:     (key: keyof TranslationDict["shop"])     => string;
  product:  (key: keyof TranslationDict["product"])  => string;
  shipping: (key: keyof TranslationDict["shipping"]) => string;
  cat:      (key: keyof TranslationDict["categories"])=> string;
  footer:   (key: keyof TranslationDict["footer"])   => string;
  admin:    (key: keyof TranslationDict["admin"])    => string;
};

// Memoized per language: t(lang) must return a stable reference, otherwise
// client components that use it as a useEffect dependency (e.g. [tx]) would
// re-run their effects on every render and cause infinite fetch loops.
const tCache = new Map<Lang, Translator>();

export function t(lang: Lang): Translator {
  const cached = tCache.get(lang);
  if (cached) return cached;
  const dict: Translator = {
    common:   (key) => translations.common[key][lang]    ?? translations.common[key]["ar"],
    nav:      (key) => translations.nav[key][lang]       ?? translations.nav[key]["ar"],
    home:     (key) => translations.home[key][lang]      ?? translations.home[key]["ar"],
    shop:     (key) => translations.shop[key][lang]      ?? translations.shop[key]["ar"],
    product:  (key) => translations.product[key][lang]   ?? translations.product[key]["ar"],
    shipping: (key) => translations.shipping[key][lang]  ?? translations.shipping[key]["ar"],
    cat:      (key) => translations.categories[key][lang] ?? translations.categories[key]["ar"],
    footer:   (key) => translations.footer[key][lang]    ?? translations.footer[key]["ar"],
    admin:    (key) => translations.admin[key][lang]     ?? translations.admin[key]["ar"],
  };
  tCache.set(lang, dict);
  return dict;
}
